/**
 * Worker entry: OpenNext's generated handler plus a `scheduled()` hook so
 * Cloudflare Cron Triggers drive the same /api/cron/* routes Vercel Cron
 * does today. The request is dispatched in-process through the handler's
 * own fetch (no public round trip) with the bearer secret the routes expect.
 */
// @ts-expect-error — generated by `opennextjs-cloudflare build`; not in git.
import handler from "../.open-next/worker.js";

import { envName, makeCounter, routeGroup, withErrorCount, type Counter } from "../src/lib/cloudflare/error-count";
import { cachedImage, isImageRequest } from "../src/lib/cloudflare/image-cache";
import { isCacheableDocumentRequest } from "../src/lib/cloudflare/page-cache";
import { BUILD_HEADER } from "../src/lib/cloudflare/page-store";
import { setPageRenderer } from "../src/lib/cloudflare/page-warm";
import { jobForSchedule } from "../src/lib/cron/schedules";

// Durable Object classes used by the cache overrides (open-next.config.ts).
// @ts-expect-error — generated file, see above.
export { DOQueueHandler, DOShardedTagCache } from "../.open-next/worker.js";

type Env = {
  CRON_SECRET?: string;
  /**
   * "1" only on the Worker that is serving production traffic. Until the
   * DNS cutover, Vercel Cron runs the jobs; a second scheduler against the
   * same database would double-send alerts and race on `sla_alerted_at`.
   */
  CRON_ENABLED?: string;
  NEXT_PUBLIC_SITE_URL?: string;
  /** Worker secrets (deploy workflow). Used only to count server errors (OPS-21). */
  NEXT_PUBLIC_SUPABASE_URL?: string;
  SUPABASE_SERVICE_ROLE_KEY?: string;
  /** Next build id (deploy workflow); marks pages so the front Worker stores only this build's. */
  BUILD_ID?: string;
};

/** Tag a page with the build that rendered it (see src/lib/cloudflare/page-store.ts). */
function withBuildId(res: Response, buildId: string | undefined): Response {
  if (!buildId) return res;
  const out = new Response(res.body, res);
  out.headers.set(BUILD_HEADER, buildId);
  return out;
}

// One counter per Worker instance, so its per-minute limit holds (OPS-21).
let errorCounter: Counter | undefined;
function counterFor(env: Env): Counter {
  errorCounter ??= makeCounter({
    url: env.NEXT_PUBLIC_SUPABASE_URL,
    key: env.SUPABASE_SERVICE_ROLE_KEY,
    env: envName(env.NEXT_PUBLIC_SITE_URL),
  });
  return errorCounter;
}

/**
 * Counts one server error and writes one log line to filter on in Workers Logs
 * ("server-error"). Status, route group and method only: no path, no query
 * string, no header. Never throws.
 */
function recordServerError(request: Request, status: number, env: Env, ctx: ExecutionContext): void {
  try {
    const { pathname } = new URL(request.url);
    console.error(
      JSON.stringify({ kind: "server-error", status, route: routeGroup(pathname), method: request.method }),
    );
    ctx.waitUntil(counterFor(env).count(pathname));
  } catch {
    // Counting must never change what the visitor gets.
  }
}

async function respond(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  const render = (req: Request) => handler.fetch(req, env, ctx);
  const waitUntil = (p: Promise<unknown>) => ctx.waitUntil(p);
  // Lets a publish re-store the pages it dropped (src/lib/cloudflare/page-warm.ts).
  setPageRenderer((req) => render(req).then((res: Response) => withBuildId(res, env.BUILD_ID)));
  if (isImageRequest(request)) return cachedImage(request, caches.default, render, waitUntil);
  // Pages are cached by the front Worker alone: a second copy here would hand
  // it old pages to re-store as new, and purging could not reach that copy.
  if (isCacheableDocumentRequest(request)) {
    return render(request).then((res: Response) => withBuildId(res, env.BUILD_ID));
  }
  return render(request);
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    // Every way out of this Worker passes here, so the count sees every answer,
    // including a 500 that a route builds itself (the lead form's "db-insert-failed").
    return withErrorCount(
      () => respond(request, env, ctx),
      (status) => recordServerError(request, status, env, ctx),
    );
  },

  async scheduled(event: ScheduledEvent, env: Env, ctx: ExecutionContext) {
    const job = jobForSchedule(event.cron);
    if (!job) {
      console.warn(`[cron] no job for expression "${event.cron}"`);
      return;
    }
    if (env.CRON_ENABLED !== "1") {
      console.log("[cron] CRON_ENABLED is not 1; skipping", job.path);
      return;
    }
    if (!env.CRON_SECRET) {
      console.warn("[cron] CRON_SECRET is not set; skipping", job.path);
      return;
    }
    const origin = (env.NEXT_PUBLIC_SITE_URL ?? "https://www.mmg-lawfirm.com").replace(/\/$/, "");
    // The scheduled publish revalidates /blog and the new post; let it re-store them too.
    setPageRenderer((req) => handler.fetch(req, env, ctx).then((res: Response) => withBuildId(res, env.BUILD_ID)));
    const request = new Request(`${origin}${job.path}`, {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler
        .fetch(request, env, ctx)
        .then((res: Response) => {
          if (!res.ok) console.error(`[cron] ${job.path} → HTTP ${res.status}`);
        })
        .catch((err: unknown) => console.error(`[cron] ${job.path} failed`, err)),
    );
  },
} satisfies ExportedHandler<Env>;
